// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy proxy and initialize
        vm.prank(address(0x1));
        c.initialize(1, 1, "test", address(0xdead));

        // Transfer ownership to address(0x2)
        vm.prank(address(0x1));
        c.transferOwnership(address(0x2));

        // Accept ownership from address(0x2)
        vm.prank(address(0x2));
        c.acceptOwnership();

        // New owner should be address(0x2), not address(0)
        assertTrue(c.owner() == address(0x2));
    }
}

