pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and initialize the contract
        address protocolFeeDest = address(0x1234);
        vm.prank(address(0xdead));
        c.initialize(1, 1, "signature", protocolFeeDest);

        // Setup actors
        address newOwner = address(0xbeef);
        address originalOwner = address(0xdead);

        // Transfer ownership to newOwner
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);

        // newOwner accepts ownership
        vm.prank(newOwner);
        c.acceptOwnership();

        // Now owner() on reference returns newOwner, on bug returns address(0)
        // Attempt to call pause from newOwner (requires owner)
        vm.prank(newOwner);
        c.pause();

        // The reference succeeds (pause is now active), the bug reverts (caller != owner)
        // Assert that the contract is paused: only true if pause succeeded
        assertTrue(c.paused());
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. Get two addresses
        address alice = address(0x1234);
        address bob = address(0x5678);

        // 2. Initialize the proxy (simulate initializer call)
        vm.prank(alice);
        c.initialize(1, 1, "signature", bob);

        // 3. Transfer ownership from current owner (alice) to bob
        vm.prank(alice);
        c.transferOwnership(bob);

        // 4. Bob accepts ownership
        vm.prank(bob);
        c.acceptOwnership();

        // 5. Now try calling pause() as bob — onlyOwner-restricted
        // On reference: owner() == bob, so pause() succeeds
        // On bug: owner() == address(0), so pause() reverts with OwnableUnauthorizedAccount(bob)
        // Wrap in try/catch to capture revert boolean
        bool paused = false;
        try c.pause() {
            paused = true;
        } catch {
            paused = false;
        }

        // Reference: paused == true; bug: paused == false
        assertTrue(paused);
    }
}

