pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address newOwner = address(0x1234);

    function setUp() public { 
        c = new C(); 
    }

    function testRegression_property() public {
        // 1. Transfer ownership to newOwner
        vm.prank(address(c)); // Contract is initially owner after deployment
        vm.deal(address(c), 1 ether); // Give contract some ETH if needed

        // The contract's initial owner after initialization is the deployer (this test contract)
        // We need to set up the initialization first
        address protocolFeeDest = address(0x5678);

        // Initialize the contract (it uses initializer modifier)
        vm.prank(address(this));
        c.initialize(1, 1, "test", protocolFeeDest);

        // Now the owner is address(this)
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // 2. Have newOwner accept ownership
        vm.prank(newOwner);
        c.acceptOwnership();

        // 3. Now check if renounceOwnership() called by newOwner succeeds on reference but reverts on bug
        vm.prank(newOwner);
        bool success;
        try c.renounceOwnership() {
            success = true;
        } catch {
            success = false;
        }

        // Reference: newOwner becomes owner after acceptOwnership, so renounceOwnership succeeds
        // Bug: owner() always returns address(0), so renounceOwnership reverts with OwnableUnauthorizedAccount
        assertTrue(success, "renounceOwnership should succeed in reference");
    }
}

