pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. Deploy and get the initial owner
        address initialOwner = address(this);

        // 2. Transfer ownership to a new address
        address newOwner = address(0x1234);
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        // 3. Verify pending owner is set
        assertEq(c.pendingOwner(), newOwner, "pending owner should be set");

        // 4. New owner tries to accept ownership
        bool ok;
        vm.prank(newOwner);
        try c.acceptOwnership() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract will succeed (ok = true), the buggy one will revert (ok = false)
        assertTrue(ok, "acceptOwnership should succeed");
    }
}

