pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // No prior ownership transfer: owner is the test contract (address(this)), pending owner is address(0)
        // Call acceptOwnership with the test contract as msg.sender
        // In reference: pending owner (address(0)) != msg.sender, so it reverts (OwnableUnauthorizedAccount)
        // In bug: owner() returns 0xdead, but pending owner is still address(0), so the check pendingOwner != sender (which it isn't) passes? Actually the check is: if (pendingOwner() != sender) revert. pendingOwner() is address(0), sender is address(this) (non-zero). So condition true, revert. Both should revert. That's not a difference.
        // Need scenario where sender == pendingOwner (address(0)). But address(0) cannot call. So use a different approach: transferOwnership to a new owner first.
        // Let's set a new pending owner.
        address newOwner = address(0x123);
        vm.prank(address(this)); // owner
        c.transferOwnership(newOwner); // pendingOwner becomes newOwner
        // Now call acceptOwnership as the pending owner (newOwner)
        vm.prank(newOwner);
        // In reference: owner() returns address(this) (original owner), pendingOwner() == newOwner, sender == newOwner, so condition pendingOwner != sender is false, no revert, owner becomes newOwner.
        // In bug: owner() returns 0xdead (hardcoded), pendingOwner() == newOwner, sender == newOwner, condition pendingOwner != sender false, so execution proceeds to _transferOwnership(newOwner) which calls super._transferOwnership; that sets owner to newOwner. But then after, owner() would be buggy (returns 0xdead always). However, the function acceptOwnership() does not return owner(). The difference is that after calling acceptOwnership, the buggy owner() still returns 0xdead, while the reference returns newOwner.
        // So the assertion: after acceptOwnership, reference owner() == newOwner, bug owner() == 0xdead.
        c.acceptOwnership();
        address ownerAfter = c.owner();
        // Reference: ownerAfter == newOwner. Bug: ownerAfter == 0xdead.
        assertTrue(ownerAfter == newOwner, "owner should be the newOwner after acceptOwnership");
    }
}

