pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize the contract with a protocolFeeDestination (default royalty recipient)
        vm.startPrank(address(0x1));
        c.initialize(1, 1, "", address(0x2));
        vm.stopPrank();

        // Create an art to get a tokenId (tokenId = 1)
        // Fund some ETH for the art creation fee (we don't care about the actual amount, just need a token)
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.createArtFromFactory{value: 1 ether}(0);

        // Now set a specific royalty configuration for token 1 (different from default)
        // royaltyRecipient = address(0xdead), royaltyBPS = 1000
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config;
        config.royaltyBPS = 1000;
        config.royaltyRecipient = address(0xdead);

        // Ownership was transferred to address(0x1) during initialize, so we can use that
        vm.prank(address(0x1));
        c.updateRoyalties(1, config);

        // Now call getRoyalties(1) and check the returned royaltyBPS
        // Reference: should return 1000, Bug: always returns 500
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory returnedConfig = c.getRoyalties(1);
        assertTrue(returnedConfig.royaltyBPS == 1000);
    }
}

